<?php
namespace ZinCelestial\Platform\Compliance;use RuntimeException;defined('ABSPATH')||exit;
final class ComplianceEngine{private array $controls=[];public function register(ComplianceControl $c):void{$this->controls[$c->id]=$c;}public function evaluate(string $id,array $evidence,int $now):ComplianceResult{$c=$this->controls[sanitize_key($id)]??null;if(!$c)throw new RuntimeException('Unknown compliance control.');$accepted=[];$reasons=[];foreach($evidence as $e){$eid=sanitize_key((string)($e['id']??''));$type=sanitize_key((string)($e['type']??''));$at=(int)($e['collected_at']??0);$hash=(string)($e['sha256']??'');if(!$eid||!in_array($type,$c->evidence_types,true)){continue;}if($at>$now||$now-$at>$c->evidence_max_age){$reasons[]='stale_evidence';continue;}if(!preg_match('/^[a-f0-9]{64}$/',$hash)){$reasons[]='invalid_evidence_hash';continue;}$accepted[$eid]=true;} $status=count($accepted)>0?'pass':'fail';if(!$accepted&&!$reasons)$reasons[]='missing_evidence';return new ComplianceResult($c->id,$status,array_keys($accepted),array_values(array_unique($reasons)),$now);}}
